+          reason: 'exit settles bounded — the watchdog floor is 8 minutes',
+        );
+        final session = cli.sessionForTest;
+        expect(session, isNotNull);
+        expect(session!.isSealed, isTrue, reason: 'the quit seals the session');
+      } finally {
+        await io.close();
+        await keys.close();
+      }
+    },
+  );
+}
